import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.BPyF_sP4.js";const h=JSON.parse('{"title":"实践篇导读","description":"","frontmatter":{"title":"实践篇导读","bookSource":"06-case-study/README.md","bookPart":"实践篇","readingMinutes":2,"prev":{"text":"第 24 章 Agent 边缘运行时与全球优化","link":"/optimization/chapter-24.html"},"next":{"text":"第25章 研发效能","link":"/cases/chapter-25/"},"editLink":true},"headers":[],"relativePath":"cases/index.md","filePath":"06-case-study/README.md","lastUpdated":1791860601000}'),o={name:"cases/index.md"};function s(r,e,d,c,l,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="实践篇导读" tabindex="-1">实践篇导读 <a class="header-anchor" href="#实践篇导读" aria-label="Permalink to &quot;实践篇导读&quot;">​</a></h1><p>覆盖研发效能、设计工程、运维安全与企业 IT 、客户、销售与运营等领域，同时我们把世界人工智能开源大赛中的优秀作品也纳入进来，既有企业实践，也有来自开发者的前沿探索。</p><p>其中，研发效能共计7个案例，覆盖了阿里云在代码审查、代码缺陷修复、研发协作等多个领域，同时包含了将 Agent 产品化过程中的一些思考。设计工程共计2个案例，全面介绍了阿里云在Vibe Designing、GenUI 方面的思考和实践。运维安全与企业 IT 共计3个案例，介绍了畅捷通、吉利汽车、塔斯汀的大规模生产业务在智能运维方面的实践。客户、销售与运营共计4个案例，介绍了MiniMax 和 B 站构建上下文和记忆的实践，会计师事务所信永中和办公提效方面的探索，以及阿里云在智能问数领域的实践。</p><p>此外，2026 年 GOAI 世界人工智能开源大赛 Agent Infra 新智基座赛道提供了9个作品，涉及能源电力、金融、建筑工程设计、零售连锁、数字内容（游戏 / XR / 电商）、企业运营与组织治理、财务与渠道佣金结算、软件工程与交付、IT 运维与故障恢复、网络安全运营、数据工程，多达11个领域，提供了更加垂直化的实践样本。</p><p><a href="/ai-agent-handbook/cases/jev/">Jev 专题</a>关注 Agent 工作流中需要快速分类、评分与路由的结构化决策，收录模型解析、HiRoute 实践及官方实践资料。可以按以下顺序阅读：</p><ul><li><a href="/ai-agent-handbook/cases/jev/deep-dive.html">深度解析 Jev 模型：如何快速做结构化决策</a></li><li><a href="/ai-agent-handbook/cases/jev/hiroute.html">HiRoute：Jev 模型智能路由实践</a></li></ul>',6)])])}const u=a(o,[["render",s]]);export{h as __pageData,u as default};
